                                   {   'difficulty': 'Medium',
                                       'explanation': 'Split metric name, parse key-value labels in `{...}`, and cast '
                                                      'value to float.',
                                       'id': 38,
                                       'is_coding': True,
                                       'question_text': '<strong>Problem Statement:</strong><br>Implement a parser '
                                                        'extracting metric name, label dictionary, and float value '
                                                        'from Prometheus text format.',
                                       'starter_code': 'def parse_prometheus_metric(raw_line: str) -> tuple[str, '
                                                       'dict[str, str], float]:\n'
                                                       '    # Example: '
                                                       '\'http_requests_total{method="POST",status="200"} 1027.0\'\n'
                                                       "    name_part, val_str = raw_line.strip().rsplit(' ', 1)\n"
                                                       '    val = float(val_str)\n'
                                                       "    if '{' in name_part:\n"
                                                       "        name, label_part = name_part.split('{', 1)\n"
                                                       "        label_part = label_part.rstrip('}')\n"
                                                       '        labels = {}\n'
                                                       "        for item in label_part.split(','):\n"
                                                       "            k, v = item.split('=', 1)\n"
                                                       '            labels[k.strip()] = v.strip(\'"\')\n'
                                                       '        return name, labels, val\n'
                                                       '    return name_part, {}, val\n',
                                       'title': 'Coding Task 8: Prometheus Custom Metric Counter Parser'},
                                   {   'difficulty': 'Medium',
                                       'explanation': 'Parse components into integers and compare Major, Minor, and '
                                                      'Patch.',
                                       'id': 39,
                                       'is_coding': True,
                                       'question_text': '<strong>Problem Statement:</strong><br>Implement a Semantic '
                                                        'Versioning comparator <code>compare_semver(v1, v2)</code>.',
                                       'starter_code': 'def compare_semver(v1: str, v2: str) -> int:\n'
                                                       '    # Return 1 if v1 > v2, -1 if v1 < v2, 0 if v1 == v2\n'
                                                       "    nums1 = [int(x) for x in v1.split('.')]\n"
                                                       "    nums2 = [int(x) for x in v2.split('.')]\n"
                                                       '    for a, b in zip(nums1, nums2):\n'
                                                       '        if a > b: return 1\n'
                                                       '        if a < b: return -1\n'
                                                       '    return 0\n',
                                       'title': 'Coding Task 9: SemVer Version Comparator'},
