                                                      "        case 'ADD_ITEM':\n"
                                                      '            return [...state, action.payload];\n'
                                                      "        case 'REMOVE_ITEM':\n"
                                                      '            return state.filter(item => item.id !== '
                                                      'action.payload.id);\n'
                                                      "        case 'CLEAR':\n"
                                                      '            return [];\n'
                                                      '        default:\n'
                                                      '            return state;\n'
                                                      '    }\n'
                                                      '}\n'
