                                                        '    const map = {\n'
                                                        "        '&': '&amp;',\n"
                                                        "        '<': '&lt;',\n"
                                                        "        '>': '&gt;',\n"
                                                        '        \'"\': \'&quot;\',\n'
                                                        '        "\'": \'&#039;\'\n'
                                                        '    };\n'
